#!/usr/bin/env bash
#
# AIRA AI 2026 — PR #96 Permanent Staging Cutover Wizard
# Generated by the /wizard skill.
#
# Walks repository owner (rajpunkeshwarrajgautam-boop) step by step through the
# 8 manual and owner-authorized stages of the permanent staging cutover.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit it.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=8
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()
BYPASS_TOKEN=""
CHECKPOINT_NAME=""
APPROVED_SHA=""
STAGING_DB_URL=""
SOURCE_DB_URL=""

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard guides you through the controlled permanent staging cutover\n' "$DIM"
  printf '  for PR #96 (feat/commercial-staging-integration -> staging).\n'
  printf '  It ensures recovery checkpoints, verifies exact commits, runs the controlled\n'
  printf '  historical identity import, and verifies all 11 integrity gates.%s\n\n' "$RESET"
  pause "Press Enter to start the staging cutover wizard..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "Could not open browser automatically, please open: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

acquire_maintenance_bypass_token() {
  local token=""
  # 1. Environment variable
  if [[ -n "${AIRA_MAINTENANCE_BYPASS_TOKEN:-}" ]]; then
    token="$AIRA_MAINTENANCE_BYPASS_TOKEN"
    say "✓ Using existing AIRA_MAINTENANCE_BYPASS_TOKEN from operator environment."
  # 2. Local token file (mode 0600)
  elif [[ -f ".aira-maintenance-token.local" ]]; then
    token=$(tr -d ' \r\n' < ".aira-maintenance-token.local" 2>/dev/null || echo "")
    if [[ -n "$token" ]]; then
      say "✓ Loaded operator maintenance bypass token from .aira-maintenance-token.local."
    fi
  fi

  # 3. Prompt operator or generate securely
  if [[ -z "$token" ]]; then
    ask_secret token "Enter 64-character hex maintenance bypass token (or press Enter to auto-generate):"
    if [[ -z "$token" ]]; then
      say "Generating new 256-bit cryptographically secure bypass token..."
      token=$(node -e "console.log(require('crypto').randomBytes(32).toString('hex'))")
    fi
    # Write to local file with restricted mode 0600
    (umask 077 && printf '%s' "$token" > ".aira-maintenance-token.local")
    say "✓ Token securely written to .aira-maintenance-token.local (mode 0600)."
  fi

  # 4. Strict validation (fail closed on malformed or empty token)
  if [[ ! "$token" =~ ^[0-9a-fA-F]{64}$ ]]; then
    warn "SECURITY FATAL: Maintenance bypass token must be an exact 64-character hexadecimal string! Fail-closed."
    exit 1
  fi

  BYPASS_TOKEN="$token"
  export AIRA_MAINTENANCE_BYPASS_TOKEN="$BYPASS_TOKEN"
  say "✓ Maintenance bypass token active in operator environment (redacted)."
}

retire_maintenance_bypass_token() {
  rm -f .aira-maintenance-token.local
  unset AIRA_MAINTENANCE_BYPASS_TOKEN || true
  BYPASS_TOKEN=""
  note "✓ Maintenance bypass token securely retired from local environment."
}

finish() {
  _clear
  printf '\n%s%s  ✓ PR #96 Permanent Staging Cutover Protocol Complete!%s\n' "$BOLD" "$GREEN" "$RESET"
  note "Schema migrations 016–022 applied, historical identities imported, and all 11 integrity assertions verified."
  note "Permanent staging is live and certified at https://staging.virexaaiventures.com."
  printf '\n'
}

show_rollback_protocol() {
  local phase="$1"
  printf '\n%s%s🚨 CRITICAL FAILURE RECOVERY PROTOCOL [%s]%s\n' "$BOLD" "$RED" "$phase" "$RESET"
  case "$phase" in
    BEFORE_MIGRATION)
      say "Condition: Failure occurred before schema migrations 016–022 were initiated."
      say "Action: Safe to deactivate maintenance barrier immediately."
      say "Command: npx tsx scripts/staging-maintenance-control.ts --deactivate"
      ;;
    DURING_MIGRATION)
      warn "Condition: Schema migrations 016–022 failed mid-execution or were interrupted!"
      warn "DO NOT DEACTIVATE MAINTENANCE BARRIER. Schema is in an inconsistent intermediate state."
      say "Mandatory Action:"
      say "  1. Keep maintenance barrier active fail-closed."
      say "  2. Go to Neon Console (project mute-frost-50372225):"
      say "     Restore branch 'main' (br-autumn-star-b36dfu5w) from recovery checkpoint: '${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}'."
      say "  3. Verify restored branch schema is at baseline (23 public tables, migration 015)."
      say "  4. Deactivate maintenance barrier ONLY AFTER database restoration is verified."
      ;;
    AFTER_MIGRATION_BEFORE_MERGE)
      warn "Condition: Migrations 016–022 were applied, but PR #96 is NOT merged into staging."
      warn "DO NOT DEACTIVATE MAINTENANCE BARRIER. Database schema is at 022 while staging branch code is at 015."
      say "Mandatory Action:"
      say "  1. Restore permanent staging database from Neon recovery checkpoint: '${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}'."
      say "  2. Verify restored database schema is at baseline (migration 015)."
      say "  3. Deactivate maintenance barrier ONLY AFTER database restoration is verified."
      ;;
    AFTER_MERGE)
      warn "Condition: PR #96 was merged into staging, but build, health check, or certification failed."
      say "Mandatory Action:"
      say "  1. Revert merge commit on staging branch:"
      say "     git revert -m 1 <merge_commit_sha> && git push origin staging"
      say "  2. Keep maintenance barrier active fail-closed."
      say "  3. Restore permanent staging database from Neon recovery checkpoint: '${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}'."
      say "  4. Deactivate maintenance barrier ONLY AFTER both code revert and DB restore are complete."
      ;;
    AFTER_HISTORICAL_IMPORT)
      warn "Condition: Historical identity import completed, but integrity verification failed."
      say "Mandatory Action:"
      say "  1. Revert staging branch merge if merged."
      say "  2. DO NOT deactivate maintenance barrier."
      say "  3. Restore permanent staging database from Neon recovery checkpoint: '${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}'."
      say "  4. Re-verify restored database integrity to confirm clean baseline."
      say "  5. Deactivate maintenance barrier ONLY AFTER restoration is verified."
      ;;
  esac
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Authoritative Staging Cutover Procedure
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

banner "AIRA AI 2026 — PR #96 Permanent Staging Cutover"

# ── Stage 1: Verify PR #96 Candidate SHA & Release Authorization ───────────
stage "Verify PR #96 & Authorization"
say "Confirm the exact PR #96 HEAD commit SHA and ensure all CI checks passed."
open_url "https://github.com/rajpunkeshwarrajgautam-boop/AIRA-AI-2026/pull/96"
step "Verify that PR #96 is targeting branch: staging"
step "Verify that the Fast CI and Main / PR certification check runs have succeeded"

LOCAL_SHA=$(git rev-parse HEAD 2>/dev/null || echo "")
