ask CHECKPOINT_NAME "Enter Neon recovery checkpoint branch name or ID:"
CHECKPOINT_NAME="${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}"

say "Running machine verification of Neon recovery checkpoint..."
if ! npx tsx scripts/verify-neon-checkpoint.ts "$CHECKPOINT_NAME"; then
  warn "SECURITY FATAL: Neon recovery checkpoint verification failed! Aborting cutover fail-closed."
  exit 1
fi

note "✓ Machine-verifiable Neon recovery checkpoint confirmed active."
pause "Press Enter to proceed to staging write isolation..."

# ── Stage 3: Staging Maintenance Barrier & Write Isolation ──────────────────
stage "Staging Maintenance Barrier & Write Isolation Gate"
say "Activate the authoritative staging maintenance barrier on permanent staging."
say "This enforces read-only defaults and table triggers to block background writers and older deployments."
step "Announce temporary maintenance on staging.virexaaiventures.com"

step "Owner Credential Retirement & Connection Draining Runbook:"
say "  a. Execute role separation DDL: psql \"\$STAGING_DB_URL\" -f scripts/setup-staging-role-separation.sql"
say "     (Provisions aira_staging_runtime without CREATE privileges or DML on _aira_staging_maintenance)"
say "  b. Update Vercel Preview (staging) DATABASE_URL to use aira_staging_runtime"
